function FooterLinks({
  title,
  links,
  as: Heading,
}: {
  title: string;
  links: { name: string; href: string }[];
  as: "h2" | "h5";
}) {
  return (
    <div>
      <Heading className="font-work text-[20px] font-bold leading-[26px] text-white">
        {title}
      </Heading>
      <ul className="mt-5 flex flex-col gap-5">
        {links.map((link) => (
          <li key={link.name} className="leading-[16.94px]">
            <Link
              href={link.href}
              className="font-inter text-[14px] leading-[16.94px] text-white transition-colors duration-200 hover:text-ta-yellow"
            >
              {link.name}
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default function Footer() {
  return (
    <footer className="bg-black text-white">
      <div className="ta-container pb-10 pt-[50px] lg:h-[436px] lg:pb-0">
        <div className="grid grid-cols-1 gap-12 md:grid-cols-2 lg:grid-cols-[412px_365px_1fr] lg:gap-0">
          {/* About / Logo */}
          <div>
            <Link href="/" className="inline-block pt-[2px]">
              <Image
                src={aviationist_logods}
                alt="The Aviationist"
                className="h-[27px] w-auto"
              />
            </Link>

            <p className="mt-[15px] max-w-[310px] font-inter text-[16px] leading-[18px] text-white">
              The Aviationist is run by David Cenciotti (cenciotti@theaviationist.com), a
              journalist based in Rome, Italy, who launched the blog in 2006: since then, The
              Aviationist has become one of world&apos;s most authoritative and read military
              aviation websites.
            </p>

            <div className="mt-[22px] flex flex-wrap gap-[22.6px]">
              {socialLinks.map((social) => (
                <a
                  key={social.label}
                  href={social.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={social.label}
                  className="block transition-transform duration-200 hover:scale-[1.2]"
                >
                  {social.icon}
                </a>
              ))}
            </div>
          </div>

          <FooterLinks title="Website Links" links={websiteLinks} as="h5" />
          <FooterLinks title="Other Resources" links={resourceLinks} as="h2" />
        </div>
      </div>

      {/* Gradient divider */}
      <div className="mx-auto h-[3px] w-full max-w-[1272px] bg-gradient-to-r from-[#FFD11A] to-[#DE772E]" />

      {/* Copyright */}
      <div className="mt-[19px] flex h-[77px] items-start justify-center px-[10px] pt-[19px]">
        <p className="text-center font-open text-[14px] leading-[19.07px] text-white">
          Copyright © {new Date().getFullYear()}
        </p>
      </div>
    </footer>
  );
}
